/bin/zsh -lc "python3 -c \"
lines = open('<F2>/sympy/series/gruntz.py').readlines()
call_lines = {421, 449, 451, 453}
funcs = []
for i, l in enumerate(lines):
    if l.startswith('def ') or l.startswith('    def '):
        funcs.append((i+1, l.strip().split('(')[0].replace('def ','')))
result = {}
for cl in call_lines:
    f = None
    for start, name in reversed(funcs):
        if start <= cl:
            f = name
            break
    result[cl] = f
print(result)
\""
